import {resetRecruitFilters,toggleRecruitSelection} from './recruit-selection.js?v=175';
import {aiDifficultyControl} from './ai-difficulty.js?v=175';
import {OBSERVER_COLORS} from './map-markers.js?v=175';
import {setupScreen} from './screens.js?v=175';
import {PROTOCOL,playingMembers,newRoom,joinRoom,disconnect,execute,roomView,restoreRoom} from './multiplayer-core.js?v=175';
import {RelayPeer} from './relay.js?v=175';
import {COUNTRIES,COUNTRY,DISPLAY_ROSTER,DEFAULT_TEAM_IDS} from './data.js?v=175';
import {esc,button,flag,portrait,statlines,talents,nationalities} from './ui.js?v=175';
const ACTIVE='sigma-active-multiplayer';
const SAVE='sigma2040-multiplayer-v1',BACKUP='sigma2040-multiplayer-before-free-actions-v82';
const uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24)),b=>b.toString(16).padStart(2,'0')).join('');
const powers=COUNTRIES.filter(c=>c.power);
export class Multiplayer{
 constructor(hooks){this.hooks=hooks;this.active=false;this.snapshot=null;this.peer=null;this.links=new Map();this.pending=null;this.status='';this.savedError=false;this.epoch=0;this.seq=0;this.timer=setInterval(()=>this.tick(),3000);}
 get observer(){return !!this.snapshot?.observer;}
 observe(country){if(!this.host||!this.observer)return;this.observedCountry=country;this.hooks.close();this.receive(roomView(this.room,this.token,country));}
 get host(){return !!this.room;}
 get me(){return this.snapshot?.members.find(m=>m.country===this.snapshot.country);}
 hasSave(){try{return !!localStorage.getItem(SAVE);}catch{return false;}}
 invitation(){try{const f=new URLSearchParams(location.hash.slice(1));return f.get('sigma')||'';}catch{return '';}}
 parseInvitation(value){const input=String(value).trim();let code=input;if(input.includes('#'))code=new URLSearchParams(input.split('#')[1]).get('sigma')||'';const [id,invite]=code.split('.');if(!/^[a-zA-Z0-9-]{20,80}$/.test(id||'')||!/^[a-zA-Z0-9-]{20,80}$/.test(invite||''))throw Error('Collez le lien d’invitation complet.');return {id,invite};}
 entry(mode=this.entryMode||'join'){if(this.active){this.panel();return;}this.entryMode=mode;const name=document.querySelector('#mpName')?.value||this.name||'Joueur';this.hooks.modal(`<div class="simple-modal mp-dialog"><span class="eyebrow">RÉSEAU SIGMA · 2 À 6 JOUEURS</span><h2>Multijoueur</h2>${this.hasSave()?button('Reprendre ma partie hébergée','mp-resume','primary wide'):''}<div class="mp-entry-tabs">${button('Rejoindre une partie','mp-entry-join',mode==='join'?'primary':'')}${button('Créer une partie','mp-entry-host',mode==='host'?'primary':'')}</div><label>Votre pseudo<input id="mpName" maxlength="30" value="${esc(name)}" autocomplete="nickname"></label>${mode==='join'?`<label>Lien d’invitation<input id="mpInvite" value="${esc(this.invitation())}" placeholder="Collez le lien reçu de l’hôte" spellcheck="false"></label>${button('Rejoindre et composer mon équipe','mp-join','primary wide')}<p>Vous choisirez votre pays et vos quatre agents dans le salon.</p>`:`<p>Créez le salon, partagez l’invitation, puis composez votre équipe. La partie attendra la confirmation de tous les joueurs.</p>${button('Créer le salon','mp-create','primary wide')}<label class="mp-import">Importer une sauvegarde multijoueur<input type="file" id="mpImport" accept=".json,application/json"></label>`}<p class="muted">L’hôte conserve la sauvegarde et doit garder le jeu ouvert. Aucun temps limite par tour.</p></div>`);}
 async restoreSession(){
  let saved,active;try{saved=JSON.parse(localStorage.getItem(SAVE)||'null');active=JSON.parse(sessionStorage.getItem(ACTIVE)||'null');}catch{}
  const invite=this.invitation();
  // A host opening their own invitation must resume the authoritative room, not join as a guest.
  if(saved&&(active?.host&&active.details?.id===saved.id||invite===saved.id+'.'+saved.invite)){await this.resume();return true;}
  if(active&&!active.host&&active.details){await this.connect(null,active.details,active.name||'Joueur');return true;}
  return false;
 }
 async loadPeer(){}
 async connect(room,details,name){
  if(this.active)throw Error('Quittez votre session actuelle avant de rejoindre une autre partie.');
  await this.loadPeer();this.active=true;this.room=room;this.details=room?{id:room.id,invite:room.invite}:details;this.status='Connexion au salon…';this.epoch++;const epoch=this.epoch;
  if(room)this.token=room.members.find(m=>m.host).token;
  else{try{this.token=sessionStorage.getItem('sigma-seat-'+details.id)||localStorage.getItem('sigma-seat-'+details.id)||uid();sessionStorage.setItem('sigma-seat-'+details.id,this.token);localStorage.setItem('sigma-seat-'+details.id,this.token);}catch{this.token=uid();}}
  this.name=name;try{sessionStorage.setItem(ACTIVE,JSON.stringify({host:!!room,details:this.details,name}));}catch{}if(this.host)this.publish();this.peer=new (globalThis.Peer||RelayPeer)(room?'sigma2040-'+room.id:undefined,{details:this.details,hostToken:this.host?this.token:null});
  this.peer.on('open',()=>{if(epoch!==this.epoch)return;this.status=this.host?'':'Connexion à l’hôte…';if(this.host){this.publish();}else this.connectGuest();this.refreshPanel();});
  this.peer.on('connection',conn=>{if(epoch!==this.epoch||!this.host){conn.close();return;}this.attachHost(conn);});
  this.peer.on('disconnected',()=>{if(epoch===this.epoch&&!this.peer.destroyed){this.status='Connexion au service de liaison interrompue. Reconnexion…';try{this.peer.reconnect();}catch{}}});
  this.peer.on('error',e=>{if(epoch!==this.epoch)return;this.status=e.type==='unavailable-id'?'Ce salon est déjà ouvert ailleurs. Fermez l’autre session avant de le reprendre.':e.type==='peer-unavailable'?'Hôte introuvable. Il doit ouvrir ou reprendre la partie.':'Connexion impossible pour le moment. Vérifiez votre réseau puis réessayez.';this.hooks.toast(this.status);if(this.snapshot)this.hooks.render();this.refreshPanel();});
  this.peer.on('recovered',()=>{if(epoch!==this.epoch)return;this.status='';if(this.host)this.publish();else this.hooks.render();if(document.querySelector('dialog[open] #mpLobby'))this.panel();});
  this.panel();
 }
 create(name,country){if(this.hasSave()&&!confirm('Créer ce salon remplacera la sauvegarde multijoueur hébergée sur cet appareil. Continuer ?'))return;return this.connect(newRoom(uid(),uid(),uid(),name,country),null,name);}
 resume(raw=null){const original=raw?JSON.stringify(raw):localStorage.getItem(SAVE),parsed=JSON.parse(original),room=restoreRoom(parsed);if(parsed.protocol===1&&!localStorage.getItem(BACKUP))localStorage.setItem(BACKUP,original);return this.connect(room,null,room.members.find(m=>m.host).name);}
 connectGuest(){if(!this.active||this.host||this.connection?.open||this.connecting)return;this.connecting=true;this.status='Connexion à l’hôte…';const conn=this.peer.connect('sigma2040-'+this.details.id,{reliable:true,serialization:'binary'});this.connection=conn;const epoch=this.epoch;this.lastHost=Date.now();conn.on('open',()=>{if(epoch!==this.epoch)return;this.connecting=false;conn.send({kind:'hello',protocol:PROTOCOL,invite:this.details.invite,token:this.token,name:this.name});});conn.on('data',data=>{if(epoch!==this.epoch||this.connection!==conn)return;this.lastHost=Date.now();if(data?.kind==='snapshot'){this.status='';this.receive(data.value);}else if(data?.kind==='ack'){this.finishPending(data);}else if(data?.kind==='error'){this.hooks.toast(data.message);this.status=data.message;this.refreshPanel();}else if(data?.kind==='pong'){}else if(data?.kind==='removed'){this.leave();this.hooks.toast('Votre pays a été confié à un PNJ par l’hôte.');}});conn.on('close',()=>{if(epoch!==this.epoch||this.connection!==conn)return;this.connecting=false;this.status='Hôte déconnecté — la partie est en pause.';this.hooks.render();});conn.on('error',()=>{this.connecting=false;this.status='Liaison avec l’hôte impossible. Réessayez depuis un autre réseau.';this.refreshPanel();});setTimeout(()=>{if(epoch===this.epoch&&this.connection===conn&&!conn.open){this.connecting=false;this.retryPaused=true;conn.close();this.status='La liaison avec l’hôte n’a pas abouti. Vérifiez qu’il est connecté ; certains réseaux peuvent bloquer la connexion.';this.refreshPanel();}},25000).unref?.();}
 attachHost(conn){let token=null,last=Date.now();const epoch=this.epoch;conn.on('data',data=>{
  if(epoch!==this.epoch||!this.room||!data||typeof data!=='object')return;
  try{
   if(JSON.stringify(data).length>20000)throw Error('Message trop volumineux.');
   if(!token){if(data.kind!=='hello'||data.protocol!==PROTOCOL)throw Error('Version incompatible. Rechargez le jeu.');const member=joinRoom(this.room,data);token=member.token;const old=this.links.get(token);if(old?.conn!==conn)old?.conn.close();this.links.set(token,{conn,last:Date.now()});this.publish();return;}
   const link=this.links.get(token);if(link?.conn!==conn)return;link.last=Date.now();last=link.last;
   if(data.kind==='ping'){const member=this.room.members.find(m=>m.token===token);if(member&&!member.connected){member.connected=true;member.ready=false;this.room.revision++;this.publish();}conn.send({kind:'pong'});return;}
   const member=this.room.members.find(m=>m.token===token);if(!member)throw Error('Place indisponible.');
   const result=execute(this.room,token,data);this.publish();conn.send({kind:'ack',seq:data.seq,ok:true,...result});
  }catch(e){if(data?.seq)conn.send({kind:'ack',seq:data.seq,ok:false,message:e.message});else{conn.send({kind:'error',message:e.message});setTimeout(()=>conn.close(),100);}}
 });conn.on('close',()=>{if(epoch===this.epoch&&token&&this.links.get(token)?.conn===conn){this.links.delete(token);disconnect(this.room,token);this.publish();}});conn.on('error',()=>{});setTimeout(()=>{if(!token&&epoch===this.epoch)conn.close();},35000).unref?.();}
 persist(){if(!this.room)return;try{localStorage.setItem(SAVE,JSON.stringify(this.room));this.savedError=false;}catch{this.savedError=true;this.hooks.toast('Sauvegarde multijoueur indisponible. Exportez la partie depuis le salon.');}}
 publish(){if(!this.room)return;this.persist();this.receive(roomView(this.room,this.token,this.observedCountry));for(const [token,link] of this.links){if(!this.room.members.some(m=>m.token===token)){link.conn.send({kind:'removed'});link.conn.close();this.links.delete(token);continue;}if(link.conn.open)link.conn.send({kind:'snapshot',value:roomView(this.room,token)});}if(document.querySelector('dialog[open] #mpLobby'))this.panel();}
 receive(snapshot){if(!snapshot||snapshot.protocol!==PROTOCOL)return;if(this.snapshot&&snapshot.revision<this.snapshot.revision)return;const previous=this.snapshot;this.snapshot=snapshot;this.seq=Math.max(this.seq,snapshot.lastSeq);if(snapshot.game&&previous?.phase==='lobby')this.hooks.close();if(snapshot.game)this.hooks.state(snapshot.game,previous?.game);else if(snapshot.phase!=='lobby')this.hooks.render();if(snapshot.phase==='lobby'||document.querySelector('dialog[open] #mpLobby'))this.panel();}
 command(kind,payload={}){if(!this.active||!this.snapshot)return Promise.reject(Error('Attendez la connexion au salon.'));if(this.pending)return Promise.reject(Error('Un ordre attend encore la confirmation de l’hôte.'));if(this.observer&&!['observer','start','replace','ai-difficulty'].includes(kind))return Promise.reject(Error('Observateur : consultation uniquement.'));const message={protocol:PROTOCOL,seq:++this.seq,turn:this.snapshot.game?.turn,kind,payload};if(this.host){try{const result=execute(this.room,this.token,message);this.publish();return Promise.resolve(result);}catch(e){return Promise.reject(e);}}
  if(!this.connection?.open||this.status)return Promise.reject(Error('La connexion avec l’hôte est interrompue.'));
  return new Promise((resolve,reject)=>{this.pending={message,resolve,reject,sent:Date.now()};this.connection.send(message);this.hooks.render();});
 }
 finishPending(data){if(this.pending?.message.seq!==data.seq)return;const pending=this.pending;this.pending=null;data.ok?pending.resolve(data):pending.reject(Error(data.message));this.hooks.render();}
 tick(){if(!this.active)return;const now=Date.now();if(this.host){let changed=false;for(const [token,link] of this.links){const member=this.room.members.find(m=>m.token===token);if(member?.connected&&now-link.last>15000){disconnect(this.room,token);changed=true;}}if(changed)this.publish();}
  else{if(this.connection?.open){this.connection.send({kind:'ping'});if(now-this.lastHost>15000&&!this.status){this.status='Connexion perdue — attente de l’hôte.';this.hooks.render();}if(this.pending&&now-this.pending.sent>4000){this.pending.sent=now;this.connection.send(this.pending.message);}}else if(this.peer?.open&&!this.retryPaused)this.connectGuest();}}
 leave(){try{sessionStorage.removeItem(ACTIVE);}catch{}this.epoch++;this.active=false;this.peer?.destroy();this.peer=null;this.links.clear();this.room=null;this.snapshot=null;this.connection=null;this.connecting=false;this.retryPaused=false;this.pending?.reject(Error('Session quittée.'));this.pending=null;this.status='';this.seq=0;this.draft=null;this.draftCountry=null;this.observedCountry=null;this.hooks.leave();}
 export(backup=false){if(backup){const raw=localStorage.getItem(BACKUP);if(!raw)throw Error('Aucune copie multijoueur antérieure dans ce navigateur.');const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sigma2040-multi-avant-economie-v82.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(!this.room)throw Error('Seul l’hôte possède la sauvegarde complète.');const url=URL.createObjectURL(new Blob([JSON.stringify(this.room)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`sigma2040-multi-jour-${this.room.game?.turn||1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 refreshPanel(){if(this.snapshot?.phase==='playing'){this.hooks.render();if(document.querySelector('dialog[open] #mpLobby'))this.panel();}else this.panel();}
 panel(){if(!this.active){this.entry();return;}const s=this.snapshot,me=this.me;const url=new URL(location.href);url.hash='sigma='+this.details.id+'.'+this.details.invite;
 if(me&&(this.draft==null||this.draftRoom!==s.id)){resetRecruitFilters('multi');this.draftRoom=s.id;this.draft=[...(me.agents||[])];}this.draftCountry=me?.country;
 const selected=this.draft||me?.agents||[],lobby=s?.phase==='lobby',players=s?playingMembers(s):[],observer=s?.members.find(m=>m.observer);
 const members=`<div class="mp-members">${powers.map(c=>{const m=s?.members.find(m=>m.country===c.id);return `<div class="mp-member">${flag(c.id)}<div><strong>${c.name}</strong><span>${m?esc(m.name)+(m.host?' · Hôte':''):'PNJ'}</span></div><span>${m?!m.connected?'Déconnecté':lobby?m.confirmed?'Équipe confirmée':'Équipe à confirmer':m.ready?'Prêt':'En préparation':'Automatique'}</span>${this.host&&m&&!m.host?button(lobby?'Retirer':'Confier au PNJ','mp-replace','small',`data-id="${c.id}"`):''}</div>`;}).join('')}</div>`;
 const top=`<section class="mp-lobby-header panel" id="mpLobby"><span class="eyebrow">${lobby?'PRÉPARATION MULTIJOUEUR':'SALON · '+(me?.observer?'OBSERVATEUR':COUNTRY[me?.country]?.name)}</span><h2>${lobby?(me?.observer?'Hôte observateur':'Composez votre équipe'):'Joueurs et invitation'}</h2>${observer?`<p class="notice mp-observer-notice">${esc(observer.name)} · Hôte observateur — accès à toutes les informations des joueurs. Aucune équipe ni place occupée.</p>`:''}${this.host&&lobby?`<div class="mp-role"><strong>Votre rôle</strong>${button('Hôte joueur','mp-role-player',me?.observer?'':'primary')}${button('Hôte observateur','mp-role-observer',me?.observer?'primary':'')}</div>`:''}${this.status?`<p role="status" class="notice warning">${esc(this.status)}</p>${!this.host?button('Réessayer','mp-reconnect','wide'):''}`:''}${this.savedError?'<p class="notice warning">Exportez la sauvegarde : la sauvegarde automatique a échoué.</p>':''}${aiDifficultyControl(s?.game?.aiDifficulty||s?.aiDifficulty||'normal',true,this.host&&lobby)}<label>Lien d’invitation<input readonly id="mpLink" value="${esc(url.href)}"></label>${button('Copier le lien','mp-copy','small')}<div class="mp-lobby-actions">${lobby&&me&&!me.observer?button(me.confirmed?'Équipe confirmée ✓':'Confirmer mes quatre agents','mp-team','primary',selected.length!==4||me.confirmed?'disabled':''):''}${this.host&&lobby?button('Lancer la partie','mp-start','primary',players.length<2||players.some(m=>!m.connected||!m.confirmed)?'disabled title="Tous les joueurs doivent être connectés et avoir confirmé leur équipe."':''):''}${!lobby?button('Retour au commandement','mp-play','primary'):''}${this.host?button('Exporter la sauvegarde','mp-export')+button('Exporter la copie avant changement','mp-export-backup'):''}${button('Quitter la session','mp-leave')}</div><p role="status">${lobby?`${me?.observer?'Consultation uniquement · ':selected.length+'/4 agents sélectionnés · '}${players.filter(m=>m.confirmed).length}/${players.length} équipes confirmées · 2 joueurs minimum`:'Le bouton Salon reste accessible depuis le commandement.'}</p>${members}</section>`;
 if(lobby&&me&&!me.observer){const html=setupScreen(me.country,selected,false,{header:top,taken:s.members.filter(m=>m.country!==me.country).map(m=>m.country)});if(this.hooks.lobby)this.hooks.lobby(html);else this.hooks.modal(html);return;}
 if(lobby&&this.hooks.lobby){this.hooks.lobby(`<main class="mp-observer-lobby">${top}</main>`);return;}this.hooks.modal(`<div class="simple-modal mp-dialog">${top}</div>`);
 }
 decorate(){if(!this.active||!this.snapshot?.game)return;const s=this.snapshot,me=this.me,players=playingMembers(s);const advance=document.querySelector('[data-cmd="advance"]');if(advance){advance.textContent=s.game.ended?'Voir le bilan':this.observer?'Observation en cours':me.ready?'Modifier mes ordres':s.game.event?'Communication':'Je suis prêt';advance.disabled=!s.game.ended&&(!!this.pending||!!this.status||this.observer);}
 const container=document.querySelector('.deck-content');if(!container)return;const panel=document.createElement('section');panel.className='mp-status';panel.innerHTML=`<strong>${players.filter(m=>m.ready).length}/${players.length} prêts</strong><span>${players.map(m=>esc(COUNTRY[m.country].name)+': '+(!m.connected?'déconnecté':m.ready?'prêt':'en préparation')).join(' · ')}</span>${button('Salon','mp-panel','small')}${this.status?`<p role="status">${esc(this.status)}</p>`:''}${this.pending?'<p role="status">Confirmation de l’hôte…</p>':''}${this.savedError?'<p>Échec de sauvegarde : exportez la partie.</p>':''}`;
 if(this.observer){panel.classList.add('mp-observer-status');panel.innerHTML=`<div class="mp-observer-heading"><strong>HÔTE OBSERVATEUR</strong><span>Consultation uniquement · Carte : tous les agents des joueurs</span></div><label>Joueur observé <select id="mpObserveCountry">${players.map(m=>`<option value="${m.country}" ${s.game.player===m.country?'selected':''}>${esc(m.name)} · ${COUNTRY[m.country].name}</option>`).join('')}</select></label><div class="mp-observer-legend">${players.map(m=>`<button class="btn small" data-cmd="mp-observe" data-id="${m.country}" style="--observer-color:${OBSERVER_COLORS[m.country]}" aria-pressed="${s.game.player===m.country}">${flag(m.country)} ${esc(m.name)}</button>`).join('')}</div>`+panel.innerHTML;}container.prepend(panel);
 if(this.observer)for(const el of document.querySelectorAll('[data-tech-drag]'))el.draggable=false;
 if(me.ready||this.observer){for(const el of document.querySelectorAll('[data-cmd]'))if(['government-favor','deploy','travel','agent-rest','recruit','confidence','confirm-order','cancel','confirm-cancel','cancel-tech','confirm-cancel-tech','cancel-cyber','confirm-cancel-cyber','tech-drone','confidence','tech','hire','share-confirm','request-accept','request-decline','event','mp-share-yes','mp-share-no'].includes(el.dataset.cmd))el.disabled=true;}
 const footer=document.querySelector('.command-deck > footer span');if(footer)footer.textContent=this.observer?'HÔTE OBSERVATEUR · CONSULTATION UNIQUEMENT':this.host?'HÔTE · SAUVEGARDE MULTI LOCALE':'INVITÉ · SAUVEGARDE CHEZ L’HÔTE';
 }
 async handle(cmd,id){const $=q=>document.querySelector(q);switch(cmd){
  case 'mp-role-player':case 'mp-role-observer':await this.command('observer',{observer:cmd==='mp-role-observer'});this.draft=[];this.panel();break;
  case 'mp-observe':this.observe(id);break;
  case 'mp-entry':this.entry();break;
  case 'mp-entry-join':this.entry('join');break;
  case 'mp-entry-host':this.entry('host');break;
  case 'mp-country':await this.command('country',{country:id});break;
  case 'mp-select':{if(this.draft.includes(id)||this.draft.length<4)this.draft=toggleRecruitSelection(this.draft,id,'multi');else{this.hooks.toast('Désélectionnez un agent avant d’en choisir un autre.');break;}if(this.me.confirmed)await this.command('unconfirm');this.panel();break;}
  case 'mp-create':await this.create($('#mpName').value,$('#mpCountry')?.value||'FR');break;
  case 'mp-resume':await this.resume();break;
  case 'mp-join':await this.connect(null,this.parseInvitation($('#mpInvite').value),$('#mpName').value);break;
  case 'mp-panel':this.panel();break;
  case 'mp-reconnect':if(!this.host){this.retryPaused=false;this.connection?.close();this.connecting=false;if(this.peer?.disconnected)this.peer.reconnect();else this.connectGuest();this.refreshPanel();}break;
  case 'mp-copy':try{await navigator.clipboard.writeText($('#mpLink').value);this.hooks.toast('Lien copié.');}catch{$('#mpLink').select();this.hooks.toast('Sélectionnez puis copiez le lien.');}break;
  case 'mp-ai-difficulty':await this.command('ai-difficulty',{level:id});this.panel();break;
  case 'mp-start':await this.command('start');this.hooks.close();break;
  case 'mp-play':this.hooks.close();this.hooks.render();break;
  case 'mp-team':await this.command('team',{agents:[...this.draft]});break;
  case 'mp-export-backup':this.export(true);break;
  case 'mp-export':this.export();break;
  case 'mp-replace':if(confirm('Confier '+COUNTRY[id].name+' au PNJ ? Ce joueur perdra sa place dans la session.'))await this.command('replace',{country:id});break;
  case 'mp-share-yes':case 'mp-share-no':await this.command('share-answer',{from:id,accept:cmd==='mp-share-yes'});break;
  case 'mp-leave':if(confirm(this.host?'Sauvegarder et fermer la session ? Les invités seront déconnectés.':'Quitter la session ? Votre pays restera réservé et la partie attendra votre retour.')){if(this.host){this.persist();if(this.savedError&&!confirm('La sauvegarde a échoué. Quitter tout de même ?'))return;}this.leave();this.hooks.close();}break;
 }}
}
